`timescale 1ns/1ns

module tb_RAM;

// === Global Sync Signal ===
reg llm_go_signal = 1;


    // Parameters
    parameter CLK_PERIOD = 10; // Clock period in simulation time units

    // Inputs
    reg clk;
    reg rst_n;
    reg write_en;
    reg [7:0] write_addr;
    reg [5:0] write_data;
    reg read_en;
    reg [7:0] read_addr;

    // Outputs
    wire [5:0] read_data;

    // Instantiate the module
    RAM uut (
        .clk(clk),
        .rst_n(rst_n),
        .write_en(write_en),
        .write_addr(write_addr),
        .write_data(write_data),
        .read_en(read_en),
        .read_addr(read_addr),
        .read_data(read_data)
    );

    // Clock generation
    always #((CLK_PERIOD)/2) clk = ~clk;

    integer error = 0;
    // Initial block for stimulus generation
    initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

        // Initialize inputs
        clk = 0;
        rst_n = 1;
        repeat(100) begin
            write_en = 0;
            write_addr = 0;
            write_data = 0;
            read_en = 0;
            read_addr = 0;
            // Wait for a few clock cycles
            #((CLK_PERIOD) * 5);
            // Release reset
            rst_n = 0;
            #((CLK_PERIOD) * 2);
            rst_n = 1;
            // Write operation
            write_en = 1;
            write_addr = 3'b000;
            write_data = $random;
            #((CLK_PERIOD) * 1);
            write_en = 0;
            #((CLK_PERIOD) * 1);

            // Read operation
            read_en = 1;
            read_addr = 3'b000;
            #((CLK_PERIOD) * 1);
            // $display("read_data = %b", read_data); 
            error = (read_data == write_data) ? error : error+1;
            read_en = 0;
            #((CLK_PERIOD) * 1);
            // $display("read_data = %b", read_data); 
            error = (read_data == 0) ? error : error+1;
        end
        if (error == 0) begin
            $display("===========Your Design Passed===========");
        end
        else begin
        $display("===========Error===========", error);
        end
        // Finish simulation
        $finish;
    end





        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "read_data,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", read_data);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;
        reg [7:0] addr_iter;
        reg [5:0] data_pattern;

    // 1. DECLARE VARIABLES FIRST (Top of block)




    // 2. THEN WAIT for original tests (Synchronization)
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    // Initialize signals to deterministic states
    clk = 0;
    rst_n = 1;
    write_en = 0;
    write_addr = 0;
    write_data = 0;
    read_en = 0;
    read_addr = 0;

    // Wait for clock generator to stabilize
    #10;

    // ---------------------------------------------------------
    // Test Case 1: Asynchronous Reset Check
    // ---------------------------------------------------------
    rst_n = 0;
    #20;
    rst_n = 1;
    #20;

    // ---------------------------------------------------------
    // Test Case 2: Sequential Write and Read (Addresses 0-11)
    // Covers basic functionality and address decoding
    // ---------------------------------------------------------
    for (i = 0; i < 12; i = i + 1) begin
        @(negedge clk);
        write_en = 1;
        write_addr = i;
        // Data pattern: Invert index to ensure data != address
        write_data = (i & 6'h3F) ^ 6'h3F; 
        @(negedge clk);
        write_en = 0;
    end

    // Read Back Verification
    for (i = 0; i < 12; i = i + 1) begin
        @(negedge clk);
        read_en = 1;
        read_addr = i;
        @(negedge clk);
        read_en = 0;
    end

    // ---------------------------------------------------------
    // Test Case 3: Partial Reset Vulnerability
    // The DUT loop only resets RAM[0]..RAM[7]. 
    // RAM[8]..RAM[11] are NOT reset. This test exposes that.
    // ---------------------------------------------------------
    // Write known values to index 0 (reset range) and 8 (non-reset range)
    @(negedge clk);
    write_en = 1;
    write_addr = 0; write_data = 6'h3F;
    @(negedge clk);
    write_addr = 8; write_data = 6'h3F;
    @(negedge clk);
    write_en = 0;

    // Apply Reset
    rst_n = 0;
    #20;
    rst_n = 1;
    #10;

    // Read 0 (Expect 0 due to reset)
    @(negedge clk);
    read_en = 1; read_addr = 0;
    @(negedge clk);

    // Read 8 (Expect 6'h3F if bug exists, as it's outside reset loop)
    read_addr = 8;
    @(negedge clk);
    read_en = 0;

    // ---------------------------------------------------------
    // Test Case 4: Walking 1s on Data (Bit-Level Faults)
    // Target Address 5
    // ---------------------------------------------------------
    addr_iter = 5;
    data_pattern = 6'b000001;
    for (i = 0; i < 6; i = i + 1) begin
        @(negedge clk);
        write_en = 1;
        write_addr = addr_iter;
        write_data = data_pattern;
        @(negedge clk);
        write_en = 0;

        // Read immediately to verify
        read_en = 1;
        read_addr = addr_iter;
        @(negedge clk);
        read_en = 0;

        data_pattern = data_pattern << 1;
    end

    // ---------------------------------------------------------
    // Test Case 5: Simultaneous Read/Write (Blocking/Non-Blocking)
    // Verify that Read gets OLD value and Write sets NEW value
    // ---------------------------------------------------------
    // Setup initial value at address 2
    @(negedge clk);
    write_en = 1; write_addr = 2; write_data = 6'h00;
    @(negedge clk);
    write_en = 0;

    // Simultaneous Op
    @(negedge clk);
    write_en = 1; write_addr = 2; write_data = 6'h3F;
    read_en = 1; read_addr = 2;
    @(negedge clk);
    write_en = 0; read_en = 0;

    // Verify New Value was written
    @(negedge clk);
    read_en = 1; read_addr = 2;
    @(negedge clk);
    read_en = 0;

    // ---------------------------------------------------------
    // Test Case 6: Read Enable 'Else' Branch
    // Ensure read_data drops to 0 when read_en is low
    // ---------------------------------------------------------
    @(negedge clk);
    read_en = 1; read_addr = 2;
    @(negedge clk);
    read_en = 0; // Output should become 0 here
    @(negedge clk);

    // ---------------------------------------------------------
    // Test Case 7: Out of Bounds Access (Address 12)
    // ---------------------------------------------------------
    @(negedge clk);
    write_en = 1; write_addr = 12; write_data = 6'h15;
    @(negedge clk);
    write_en = 0;
    read_en = 1; read_addr = 12;
    @(negedge clk);
    read_en = 0;

    // 4. Cleanup / Handover
    #100;
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

